/// <summary>
/// Contract class for Excise Register SOH Exception Report
/// </summary>
[DataContract]
class METExciseRegisterSOHExceptionContract implements SysOperationValidatable
{
    ItemId          itemId;
    InventSiteId    siteId;
    NoYesId         showDifferenceOnly;

}

Method.Source:
[DataMember('ItemId'),
SysOperationLabel('@SYS12836'),
SysOperationDisplayOrderAttribute('2')]
public ItemId parmItemId(ItemId _itemId = ItemId)
{
    itemId = _itemId;
    return itemId;
}

[DataMember('Site'),
SysOperationLabel('@SYS103211'),
SysOperationDisplayOrderAttribute('1')]
public InventSiteId parmSiteId(InventSiteId _site = siteId)
{
    siteId = _site;
    return siteId;
}

[DataMember('ShowDifferencesOnly'),
 SysOperationLabel('@MET:ShowDifferencesOnly'),
 SysOperationDisplayOrderAttribute('3')]
public NoYesId parmShowDifferenceOnly(NoYesId _showDifferenceOnly = showDifferenceOnly)
{
    showDifferenceOnly = _showDifferenceOnly;
    return showDifferenceOnly;
}

    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// </summary>
    /// <returns>true if valid parameters</returns>
    public boolean validate()
    {
        boolean isValid = true;

        InventSite inventSite;

        select firstonly SiteId from inventSite
            where inventSite.SiteId             == siteId
            &&    inventSite.METBondedWarehouse == NoYes::Yes;
        if(!inventSite.SiteId)
        {
            isValid = checkFailed(strFmt("@MET:SiteIsNotABondedSite",siteId));
        }


        return isValid;
    }
